"wkt":"POINT(-73.228630 10.456150)"},{"orden":12,"atributos":{"codigo":"MUE-12","nombre":"El Cerrito","zona":"sur","barrio":"EL CERRITO","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.267391 10.462360)"},{"orden":13,"atributos":{"codigo":"MUE-13","nombre":"Los Fundadores","zona":"sur","barrio":"FUNDADORES","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.262315 10.458209)"},{"orden":14,"atributos":{"codigo":"MUE-14","nombre":"Álamos","zona":"sur","barrio":"LOS ALAMOS","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.258848 10.448858)"},{"orden":15,"atributos":{"codigo":"MUE-15","nombre":"Nando Marín","zona":"sur","barrio":"NANDO MARIN I ETAPA","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.263007 10.435028)"},{"orden":16,"atributos":{"codigo":"MUE-16","nombre":"Tobías Daza","zona":"sur","barrio":"TOBÍAS DAZA","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.279466 10.449374)"},{"orden":17,"atributos":{"codigo":"MUE-17","nombre":"Alfonso López","zona":"medio","barrio":"ALFONSO LOPEZ","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.254591 10.473910)"},{"orden":18,"atributos":{"codigo":"MUE-18","nombre":"Hospital","zona":"medio","barrio":"HOSPITAL","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.254793 10.468428)"},{"orden":19,"atributos":{"codigo":"MUE-19","nombre":"Loperena","zona":"medio","barrio":"LOPERENA","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.249197 10.472856)"},{"orden":20,"atributos":{"codigo":"MUE-20","nombre":"El Amparo","zona":"medio","barrio":"EL AMPARO","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.265977 10.474919)"},{"orden":21,"atributos":{"codigo":"MUE-21","nombre":"El Carmen","zona":"medio","barrio":"EL CARMEN","exactitud":"aproximada","fuente":"barrio"},"wkt":"POINT(-73.240919 10.473494)"},{"orden":22,"atributos":{"codigo":"MUE-22","nombre":"Sicarare","zona":"medio","barrio":"SICARARE","exactitud":"aproximada","fuente":"barr